 18→async function vercelFetch(endpoint: string, options: RequestInit = {}): Promise<any> {
 19→  if (!VERCEL_API_TOKEN) {
 20→    throw new Error('VERCEL_API_TOKEN is not set');
 21→  }
 22→  const url = endpoint.startsWith('http') ? endpoint : `${VERCEL_API_BASE}${endpoint}`;
 23→  const res = await fetch(url, {
 24→    ...options,
 25→    headers: {
 26→      Authorization: `Bearer ${VERCEL_API_TOKEN}`,
 27→      'Content-Type': 'application/json',
 28→      ...options.headers,
 29→    },
 30→  });
 31→  const body = await res.text();
 32→  if (!res.ok) {
 33→    throw new Error(`Vercel API error ${res.status}: ${body}`);
 34→  }
 35→  return body ? JSON.parse(body) : {};
 36→}
