  1→/**
  2→ * NanoClaw Agent Runner
  3→ * Runs inside a container, receives config via stdin, outputs result to stdout
  4→ *
  5→ * Input protocol:
  6→ *   Stdin: Full ContainerInput JSON (read until EOF, like before)
  7→ *   IPC:   Follow-up messages written as JSON files to /workspace/ipc/input/
  8→ *          Files: {type:"message", text:"..."}.json — polled and consumed
  9→ *          Sentinel: /workspace/ipc/input/_close — signals session end
 10→ *
 11→ * Stdout protocol:
 12→ *   Each result is wrapped in OUTPUT_START_MARKER / OUTPUT_END_MARKER pairs.
 13→ *   Multiple results may be emitted (one per agent teams result).
 14→ *   Final marker after loop ends signals completion.
 15→ */
 16→
 17→import fs from 'fs';
 18→import path from 'path';
 19→import { query, HookCallback, PreCompactHookInput } from '@anthropic-ai/claude-agent-sdk';
 20→import { fileURLToPath } from 'url';
 21→
 22→interface ContainerInput {
 23→  prompt: string;
 24→  sessionId?: string;
 25→  groupFolder: string;
 26→  chatJid: string;
 27→  isMain: boolean;
 28→  isScheduledTask?: boolean;
 29→  assistantName?: string;
 30→}
 31→
 32→interface ContainerOutput {
 33→  status: 'success' | 'error';
 34→  result: string | null;
 35→  newSessionId?: string;
 36→  error?: string;
 37→}
 38→
 39→interface SessionEntry {
 40→  sessionId: string;
 41→  fullPath: string;
 42→  summary: string;
 43→  firstPrompt: string;
 44→}
 45→
 46→interface SessionsIndex {
 47→  entries: SessionEntry[];
 48→}
 49→
 50→interface SDKUserMessage {
 51→  type: 'user';
 52→  message: { role: 'user'; content: string };
 53→  parent_tool_use_id: null;
 54→  session_id: string;
 55→}
 56→
 57→const IPC_INPUT_DIR = '/workspace/ipc/input';
 58→const IPC_INPUT_CLOSE_SENTINEL = path.join(IPC_INPUT_DIR, '_close');
 59→const IPC_POLL_MS = 500;
 60→
 61→/**
 62→ * Push-based async iterable for streaming user messages to the SDK.
 63→ * Keeps the iterable alive until end() is called, preventing isSingleUserTurn.
 64→ */
 65→class MessageStream {
 66→  private queue: SDKUserMessage[] = [];
 67→  private waiting: (() => void) | null = null;
 68→  private done = false;
 69→
 70→  push(text: string): void {
 71→    this.queue.push({
 72→      type: 'user',
 73→      message: { role: 'user', content: text },
 74→      parent_tool_use_id: null,
 75→      session_id: '',
 76→    });
 77→    this.waiting?.();
 78→  }
 79→
 80→  end(): void {
 81→    this.done = true;
 82→    this.waiting?.();
 83→  }
 84→
 85→  async *[Symbol.asyncIterator](): AsyncGenerator<SDKUserMessage> {
 86→    while (true) {
 87→      while (this.queue.length > 0) {
 88→        yield this.queue.shift()!;
 89→      }
 90→      if (this.done) return;
 91→      await new Promise<void>(r => { this.waiting = r; });
 92→      this.waiting = null;
 93→    }
 94→  }
 95→}
 96→
 97→async function readStdin(): Promise<string> {
 98→  return new Promise((resolve, reject) => {
 99→    let data = '';
100→    process.stdin.setEncoding('utf8');
101→    process.stdin.on('data', chunk => { data += chunk; });
102→    process.stdin.on('end', () => resolve(data));
103→    process.stdin.on('error', reject);
104→  });
105→}
106→
107→const OUTPUT_START_MARKER = '---NANOCLAW_OUTPUT_START---';
108→const OUTPUT_END_MARKER = '---NANOCLAW_OUTPUT_END---';
109→
110→function writeOutput(output: ContainerOutput): void {
111→  console.log(OUTPUT_START_MARKER);
112→  console.log(JSON.stringify(output));
113→  console.log(OUTPUT_END_MARKER);
114→}
115→
116→function log(message: string): void {
117→  console.error(`[agent-runner] ${message}`);
118→}
119→
120→function getSessionSummary(sessionId: string, transcriptPath: string): string | null {
121→  const projectDir = path.dirname(transcriptPath);
122→  const indexPath = path.join(projectDir, 'sessions-index.json');
123→
124→  if (!fs.existsSync(indexPath)) {
125→    log(`Sessions index not found at ${indexPath}`);
126→    return null;
127→  }
128→
129→  try {
130→    const index: SessionsIndex = JSON.parse(fs.readFileSync(indexPath, 'utf-8'));
131→    const entry = index.entries.find(e => e.sessionId === sessionId);
132→    if (entry?.summary) {
133→      return entry.summary;
134→    }
135→  } catch (err) {
136→    log(`Failed to read sessions index: ${err instanceof Error ? err.message : String(err)}`);
137→  }
138→
139→  return null;
140→}
141→
142→/**
143→ * Archive the full transcript to conversations/ before compaction.
144→ */
145→function createPreCompactHook(assistantName?: string): HookCallback {
146→  return async (input, _toolUseId, _context) => {
147→    const preCompact = input as PreCompactHookInput;
148→    const transcriptPath = preCompact.transcript_path;
149→    const sessionId = preCompact.session_id;
150→

150→
151→    if (!transcriptPath || !fs.existsSync(transcriptPath)) {
152→      log('No transcript found for archiving');
153→      return {};
154→    }
155→
156→    try {
157→      const content = fs.readFileSync(transcriptPath, 'utf-8');
158→      const messages = parseTranscript(content);
159→
160→      if (messages.length === 0) {
161→        log('No messages to archive');
162→        return {};
163→      }
164→
165→      const summary = getSessionSummary(sessionId, transcriptPath);
166→      const name = summary ? sanitizeFilename(summary) : generateFallbackName();
167→
168→      const conversationsDir = '/workspace/group/conversations';
169→      fs.mkdirSync(conversationsDir, { recursive: true });
170→
171→      const date = new Date().toISOString().split('T')[0];
172→      const filename = `${date}-${name}.md`;
173→      const filePath = path.join(conversationsDir, filename);
174→
175→      const markdown = formatTranscriptMarkdown(messages, summary, assistantName);
176→      fs.writeFileSync(filePath, markdown);
177→
178→      log(`Archived conversation to ${filePath}`);
179→    } catch (err) {
180→      log(`Failed to archive transcript: ${err instanceof Error ? err.message : String(err)}`);
181→    }
182→
183→    return {};
184→  };
185→}
186→
187→function sanitizeFilename(summary: string): string {
188→  return summary
189→    .toLowerCase()
190→    .replace(/[^a-z0-9]+/g, '-')
191→    .replace(/^-+|-+$/g, '')
192→    .slice(0, 50);
193→}
194→
195→function generateFallbackName(): string {
196→  const time = new Date();
197→  return `conversation-${time.getHours().toString().padStart(2, '0')}${time.getMinutes().toString().padStart(2, '0')}`;
198→}
199→
200→interface ParsedMessage {
201→  role: 'user' | 'assistant';
202→  content: string;
203→}
204→
205→function parseTranscript(content: string): ParsedMessage[] {
206→  const messages: ParsedMessage[] = [];
207→
208→  for (const line of content.split('\n')) {
209→    if (!line.trim()) continue;
210→    try {
211→      const entry = JSON.parse(line);
212→      if (entry.type === 'user' && entry.message?.content) {
213→        const text = typeof entry.message.content === 'string'
214→          ? entry.message.content
215→          : entry.message.content.map((c: { text?: string }) => c.text || '').join('');
216→        if (text) messages.push({ role: 'user', content: text });
217→      } else if (entry.type === 'assistant' && entry.message?.content) {
218→        const textParts = entry.message.content
219→          .filter((c: { type: string }) => c.type === 'text')
220→          .map((c: { text: string }) => c.text);
221→        const text = textParts.join('');
222→        if (text) messages.push({ role: 'assistant', content: text });
223→      }
224→    } catch {
225→    }
226→  }
227→
228→  return messages;
229→}
230→
231→function formatTranscriptMarkdown(messages: ParsedMessage[], title?: string | null, assistantName?: string): string {
232→  const now = new Date();
233→  const formatDateTime = (d: Date) => d.toLocaleString('en-US', {
234→    month: 'short',
235→    day: 'numeric',
236→    hour: 'numeric',
237→    minute: '2-digit',
238→    hour12: true
239→  });
240→
241→  const lines: string[] = [];
242→  lines.push(`# ${title || 'Conversation'}`);
243→  lines.push('');
244→  lines.push(`Archived: ${formatDateTime(now)}`);
245→  lines.push('');
246→  lines.push('---');
247→  lines.push('');
248→
249→  for (const msg of messages) {
250→    const sender = msg.role === 'user' ? 'User' : (assistantName || 'Assistant');
251→    const content = msg.content.length > 2000
252→      ? msg.content.slice(0, 2000) + '...'
253→      : msg.content;
254→    lines.push(`**${sender}**: ${content}`);
255→    lines.push('');
256→  }
257→
258→  return lines.join('\n');
259→}
260→
261→/**
262→ * Check for _close sentinel.
263→ */
264→function shouldClose(): boolean {
265→  if (fs.existsSync(IPC_INPUT_CLOSE_SENTINEL)) {
266→    try { fs.unlinkSync(IPC_INPUT_CLOSE_SENTINEL); } catch { /* ignore */ }
267→    return true;
268→  }
269→  return false;
270→}
271→
272→/**
273→ * Drain all pending IPC input messages.
274→ * Returns messages found, or empty array.
275→ */
276→function drainIpcInput(): string[] {
277→  try {
278→    fs.mkdirSync(IPC_INPUT_DIR, { recursive: true });
279→    const files = fs.readdirSync(IPC_INPUT_DIR)
280→      .filter(f => f.endsWith('.json'))
281→      .sort();
282→
283→    const messages: string[] = [];
284→    for (const file of files) {
285→      const filePath = path.join(IPC_INPUT_DIR, file);
286→      try {
287→        const data = JSON.parse(fs.readFileSync(filePath, 'utf-8'));
288→        fs.unlinkSync(filePath);
289→        if (data.type === 'message' && data.text) {
290→          messages.push(data.text);
291→        }
292→      } catch (err) {
293→        log(`Failed to process input file ${file}: ${err instanceof Error ? err.message : String(err)}`);
294→        try { fs.unlinkSync(filePath); } catch { /* ignore */ }
295→      }
296→    }
297→    return messages;
298→  } catch (err) {
299→    log(`IPC drain error: ${err instanceof Error ? err.message : String(err)}`);
300→    return [];
301→  }
302→}
303→
304→/**
305→ * Wait for a new IPC message or _close sentinel.
306→ * Returns the messages as a single string, or null if _close.
307→ */
308→function waitForIpcMessage(): Promise<string | null> {
309→  return new Promise((resolve) => {
310→    const poll = () => {
311→      if (shouldClose()) {
312→        resolve(null);
313→        return;
314→      }
315→      const messages = drainIpcInput();
316→      if (messages.length > 0) {
317→        resolve(messages.join('\n'));
318→        return;
319→      }
320→      setTimeout(poll, IPC_POLL_MS);
321→    };
322→    poll();
323→  });
324→}
325→
326→/**
327→ * Run a single query and stream results via writeOutput.
328→ * Uses MessageStream (AsyncIterable) to keep isSingleUserTurn=false,
329→ * allowing agent teams subagents to run to completion.
330→ * Also pipes IPC messages into the stream during the query.
331→ */
332→async function runQuery(
333→  prompt: string,
334→  sessionId: string | undefined,
335→  mcpServerPath: string,
336→  containerInput: ContainerInput,
337→  sdkEnv: Record<string, string | undefined>,
338→  resumeAt?: string,
339→): Promise<{ newSessionId?: string; lastAssistantUuid?: string; closedDuringQuery: boolean }> {
340→  const stream = new MessageStream();
341→  stream.push(prompt);
342→
343→  // Poll IPC for follow-up messages and _close sentinel during the query
344→  let ipcPolling = true;
345→  let closedDuringQuery = false;
346→  const pollIpcDuringQuery = () => {
347→    if (!ipcPolling) return;
348→    if (shouldClose()) {
349→      log('Close sentinel detected during query, ending stream');
350→      closedDuringQuery = true;
351→      stream.end();
352→      ipcPolling = false;
353→      return;
354→    }
355→    const messages = drainIpcInput();
356→    for (const text of messages) {
357→      log(`Piping IPC message into active query (${text.length} chars)`);
358→      stream.push(text);
359→    }
360→    setTimeout(pollIpcDuringQuery, IPC_POLL_MS);
361→  };
362→  setTimeout(pollIpcDuringQuery, IPC_POLL_MS);
363→
364→  let newSessionId: string | undefined;
365→  let lastAssistantUuid: string | undefined;
366→  let messageCount = 0;
367→  let resultCount = 0;
368→
369→  // Load global CLAUDE.md as additional system context (shared across all groups)
370→  const globalClaudeMdPath = '/workspace/global/CLAUDE.md';
371→  let globalClaudeMd: string | undefined;
372→  if (!containerInput.isMain && fs.existsSync(globalClaudeMdPath)) {
373→    globalClaudeMd = fs.readFileSync(globalClaudeMdPath, 'utf-8');
374→  }
375→
376→  // Discover additional directories mounted at /workspace/extra/*
377→  // These are passed to the SDK so their CLAUDE.md files are loaded automatically
378→  const extraDirs: string[] = [];
379→  const extraBase = '/workspace/extra';
380→  if (fs.existsSync(extraBase)) {
381→    for (const entry of fs.readdirSync(extraBase)) {
382→      const fullPath = path.join(extraBase, entry);
383→      if (fs.statSync(fullPath).isDirectory()) {
384→        extraDirs.push(fullPath);
385→      }
386→    }
387→  }
388→  if (extraDirs.length > 0) {
389→    log(`Additional directories: ${extraDirs.join(', ')}`);
390→  }
391→
392→  for await (const message of query({
393→    prompt: stream,
394→    options: {
395→      cwd: '/workspace/group',
396→      additionalDirectories: extraDirs.length > 0 ? extraDirs : undefined,
397→      resume: sessionId,
398→      resumeSessionAt: resumeAt,
