120→function getSessionSummary(sessionId: string, transcriptPath: string): string | null {
121→  const projectDir = path.dirname(transcriptPath);
122→  const indexPath = path.join(projectDir, 'sessions-index.json');
123→
124→  if (!fs.existsSync(indexPath)) {
125→    log(`Sessions index not found at ${indexPath}`);
126→    return null;
127→  }
128→
129→  try {
130→    const index: SessionsIndex = JSON.parse(fs.readFileSync(indexPath, 'utf-8'));
131→    const entry = index.entries.find(e => e.sessionId === sessionId);
132→    if (entry?.summary) {
133→      return entry.summary;
134→    }
135→  } catch (err) {
136→    log(`Failed to read sessions index: ${err instanceof Error ? err.message : String(err)}`);
137→  }
