397→      resume: sessionId,
398→      resumeSessionAt: resumeAt,
399→      systemPrompt: globalClaudeMd
400→        ? { type: 'preset' as const, preset: 'claude_code' as const, append: globalClaudeMd }
401→        : undefined,
402→      allowedTools: [
403→        'Bash',
404→        'Read', 'Write', 'Edit', 'Glob', 'Grep',
