443→    const msgType = message.type === 'system' ? `system/${(message as { subtype?: string }).subtype}` : message.type;
444→    log(`[msg #${messageCount}] type=${msgType}`);
445→
446→    if (message.type === 'assistant' && 'uuid' in message) {
447→      lastAssistantUuid = (message as { uuid: string }).uuid;
