477→async function main(): Promise<void> {
478→  let containerInput: ContainerInput;
479→
480→  try {
481→    const stdinData = await readStdin();
482→    containerInput = JSON.parse(stdinData);
483→    try { fs.unlinkSync('/tmp/input.json'); } catch { /* may not exist */ }
484→    log(`Received input for group: ${containerInput.groupFolder}`);
485→  } catch (err) {
486→    writeOutput({
487→      status: 'error',
488→      result: null,
489→      error: `Failed to parse input: ${err instanceof Error ? err.message : String(err)}`
490→    });
491→    process.exit(1);
492→  }
493→
494→  // Credentials are injected by the host's credential proxy via ANTHROPIC_BASE_URL.
495→  // No real secrets exist in the container environment.
496→  const sdkEnv: Record<string, string | undefined> = { ...process.env };
497→
498→  const __dirname = path.dirname(fileURLToPath(import.meta.url));
499→  const mcpServerPath = path.join(__dirname, 'ipc-mcp-stdio.js');
500→
501→  let sessionId = containerInput.sessionId;
502→  fs.mkdirSync(IPC_INPUT_DIR, { recursive: true });
503→
504→  // Clean up stale _close sentinel from previous container runs
505→  try { fs.unlinkSync(IPC_INPUT_CLOSE_SENTINEL); } catch { /* ignore */ }
506→
507→  // Build initial prompt (drain any pending IPC messages too)
508→  let prompt = containerInput.prompt;
509→  if (containerInput.isScheduledTask) {
510→    prompt = `[SCHEDULED TASK - The following message was sent automatically and is not coming directly from the user or group.]\n\n${prompt}`;
511→  }
512→  const pending = drainIpcInput();
513→  if (pending.length > 0) {
514→    log(`Draining ${pending.length} pending IPC messages into initial prompt`);
515→    prompt += '\n' + pending.join('\n');
516→  }
517→
518→  // Query loop: run query → wait for IPC message → run new query → repeat
519→  let resumeAt: string | undefined;
520→  try {
521→    while (true) {
522→      log(`Starting query (session: ${sessionId || 'new'}, resumeAt: ${resumeAt || 'latest'})...`);
523→
524→      const queryResult = await runQuery(prompt, sessionId, mcpServerPath, containerInput, sdkEnv, resumeAt);
525→      if (queryResult.newSessionId) {
526→        sessionId = queryResult.newSessionId;
527→      }
528→      if (queryResult.lastAssistantUuid) {
529→        resumeAt = queryResult.lastAssistantUuid;
530→      }
531→
532→      // If _close was consumed during the query, exit immediately.
533→      // Don't emit a session-update marker (it would reset the host's
534→      // idle timer and cause a 30-min delay before the next _close).
535→      if (queryResult.closedDuringQuery) {
536→        log('Close sentinel consumed during query, exiting');
537→        break;
538→      }
539→
540→      // Emit session update so host can track it
541→      writeOutput({ status: 'success', result: null, newSessionId: sessionId });
542→
543→      log('Query ended, waiting for next IPC message...');
544→
545→      // Wait for the next message or _close sentinel
546→      const nextMessage = await waitForIpcMessage();
547→      if (nextMessage === null) {
548→        log('Close sentinel received, exiting');
549→        break;
550→      }
551→
552→      log(`Got new message (${nextMessage.length} chars), starting new query`);
553→      prompt = nextMessage;
554→    }
555→  } catch (err) {
556→    const errorMessage = err instanceof Error ? err.message : String(err);
557→    log(`Agent error: ${errorMessage}`);
558→    writeOutput({
559→      status: 'error',
560→      result: null,
561→      newSessionId: sessionId,
562→      error: errorMessage
563→    });
564→    process.exit(1);
565→  }
566→}
