 54→interface VolumeMount {
 55→  hostPath: string;
 56→  containerPath: string;
 57→  readonly: boolean;
 58→}
 59→
 60→function buildVolumeMounts(
 61→  group: RegisteredGroup,
 62→  isMain: boolean,
 63→): VolumeMount[] {
 64→  const mounts: VolumeMount[] = [];
 65→  const projectRoot = process.cwd();
 66→  const groupDir = resolveGroupFolderPath(group.folder);
 67→
 68→  if (isMain) {
 69→    // Main gets the project root read-only. Writable paths the agent needs
 70→    // (group folder, IPC, .claude/) are mounted separately below.
 71→    // Read-only prevents the agent from modifying host application code
 72→    // (src/, dist/, package.json, etc.) which would bypass the sandbox
 73→    // entirely on next restart.
 74→    mounts.push({
 75→      hostPath: projectRoot,
 76→      containerPath: '/workspace/project',
 77→      readonly: true,
 78→    });
 79→
 80→    // Shadow .env so the agent cannot read secrets from the mounted project root.
 81→    // Credentials are injected by the credential proxy, never exposed to containers.
 82→    const envFile = path.join(projectRoot, '.env');
 83→    if (fs.existsSync(envFile)) {
 84→      mounts.push({
 85→        hostPath: '/dev/null',
 86→        containerPath: '/workspace/project/.env',
 87→        readonly: true,
 88→      });
 89→    }
 90→
 91→    // Main also gets its group folder as the working directory
 92→    mounts.push({
 93→      hostPath: groupDir,
 94→      containerPath: '/workspace/group',
 95→      readonly: false,
 96→    });
 97→  } else {
 98→    // Other groups only get their own folder
 99→    mounts.push({
100→      hostPath: groupDir,
101→      containerPath: '/workspace/group',
102→      readonly: false,
103→    });
104→
105→    // Global memory directory (read-only for non-main)
106→    // Only directory mounts are supported, not file mounts
107→    const globalDir = path.join(GROUPS_DIR, 'global');
108→    if (fs.existsSync(globalDir)) {
109→      mounts.push({
110→        hostPath: globalDir,
111→        containerPath: '/workspace/global',
112→        readonly: true,
113→      });
114→    }
115→  }
116→
117→  // Per-group Claude sessions directory (isolated from other groups)
118→  // Each group gets their own .claude/ to prevent cross-group session access
119→  const groupSessionsDir = path.join(
120→    DATA_DIR,
121→    'sessions',
122→    group.folder,
123→    '.claude',
124→  );
125→  fs.mkdirSync(groupSessionsDir, { recursive: true });
126→  const settingsFile = path.join(groupSessionsDir, 'settings.json');
127→  if (!fs.existsSync(settingsFile)) {
128→    fs.writeFileSync(
129→      settingsFile,
130→      JSON.stringify(
131→        {
132→          env: {
133→            // Enable agent swarms (subagent orchestration)
134→            // https://code.claude.com/docs/en/agent-teams#orchestrate-teams-of-claude-code-sessions
135→            CLAUDE_CODE_EXPERIMENTAL_AGENT_TEAMS: '1',
136→            // Load CLAUDE.md from additional mounted directories
137→            // https://code.claude.com/docs/en/memory#load-memory-from-additional-directories
138→            CLAUDE_CODE_ADDITIONAL_DIRECTORIES_CLAUDE_MD: '1',
139→            // Enable Claude's memory feature (persists user preferences between sessions)
140→            // https://code.claude.com/docs/en/memory#manage-auto-memory
141→            CLAUDE_CODE_DISABLE_AUTO_MEMORY: '0',
142→          },
143→        },
144→        null,
145→        2,
146→      ) + '\n',
147→    );
148→  }
149→
150→  // Sync skills from container/skills/ into each group's .claude/skills/
151→  const skillsSrc = path.join(process.cwd(), 'container', 'skills');
152→  const skillsDst = path.join(groupSessionsDir, 'skills');
153→  if (fs.existsSync(skillsSrc)) {
154→    for (const skillDir of fs.readdirSync(skillsSrc)) {
155→      const srcDir = path.join(skillsSrc, skillDir);
156→      if (!fs.statSync(srcDir).isDirectory()) continue;
157→      const dstDir = path.join(skillsDst, skillDir);
158→      fs.cpSync(srcDir, dstDir, { recursive: true });
159→    }
160→  }
161→  mounts.push({
162→    hostPath: groupSessionsDir,
163→    containerPath: '/home/node/.claude',
164→    readonly: false,
165→  });
166→
167→  // Per-group IPC namespace: each group gets its own IPC directory
168→  // This prevents cross-group privilege escalation via IPC
169→  const groupIpcDir = resolveGroupIpcPath(group.folder);
170→  fs.mkdirSync(path.join(groupIpcDir, 'messages'), { recursive: true });
171→  fs.mkdirSync(path.join(groupIpcDir, 'tasks'), { recursive: true });
172→  fs.mkdirSync(path.join(groupIpcDir, 'input'), { recursive: true });
173→  mounts.push({
174→    hostPath: groupIpcDir,
175→    containerPath: '/workspace/ipc',
176→    readonly: false,
177→  });
178→
179→  // Copy agent-runner source into a per-group writable location so agents
180→  // can customize it (add tools, change behavior) without affecting other
181→  // groups. Recompiled on container startup via entrypoint.sh.
182→  const agentRunnerSrc = path.join(
183→    projectRoot,
184→    'container',
185→    'agent-runner',
186→    'src',
187→  );
188→  const groupAgentRunnerDir = path.join(
189→    DATA_DIR,
190→    'sessions',
191→    group.folder,
192→    'agent-runner-src',
193→  );
194→  if (!fs.existsSync(groupAgentRunnerDir) && fs.existsSync(agentRunnerSrc)) {
195→    fs.cpSync(agentRunnerSrc, groupAgentRunnerDir, { recursive: true });
196→  }
197→  mounts.push({
198→    hostPath: groupAgentRunnerDir,
199→    containerPath: '/app/src',
200→    readonly: false,
201→  });
202→
203→  // Additional mounts validated against external allowlist (tamper-proof from containers)
204→  if (group.containerConfig?.additionalMounts) {
205→    const validatedMounts = validateAdditionalMounts(
206→      group.containerConfig.additionalMounts,
207→      group.name,
208→      isMain,
209→    );
210→    mounts.push(...validatedMounts);
211→  }
212→
213→  return mounts;
214→}
