216→function buildContainerArgs(
217→  mounts: VolumeMount[],
218→  containerName: string,
219→): string[] {
220→  const args: string[] = ['run', '-i', '--rm', '--name', containerName];
221→
222→  // Pass host timezone so container's local time matches the user's
223→  args.push('-e', `TZ=${TIMEZONE}`);
224→
225→  // Route API traffic through the credential proxy (containers never see real secrets)
226→  args.push(
227→    '-e',
228→    `ANTHROPIC_BASE_URL=http://${CONTAINER_HOST_GATEWAY}:${CREDENTIAL_PROXY_PORT}`,
229→  );
230→
231→  // Mirror the host's auth method with a placeholder value.
232→  // API key mode: SDK sends x-api-key, proxy replaces with real key.
233→  // OAuth mode:   SDK exchanges placeholder token for temp API key,
234→  //               proxy injects real OAuth token on that exchange request.
235→  const authMode = detectAuthMode();
236→  if (authMode === 'api-key') {
237→    args.push('-e', 'ANTHROPIC_API_KEY=placeholder');
238→  } else {
239→    args.push('-e', 'CLAUDE_CODE_OAUTH_TOKEN=placeholder');
240→  }
241→
242→  // Pass Vercel API token if configured
243→  const envSecrets = readEnvFile(['VERCEL_API_TOKEN']);
244→  if (envSecrets.VERCEL_API_TOKEN) {
245→    args.push('-e', `VERCEL_API_TOKEN=${envSecrets.VERCEL_API_TOKEN}`);
246→  }
247→
248→  // Runtime-specific args for host gateway resolution
249→  args.push(...hostGatewayArgs());
250→
251→  // Run as host user so bind-mounted files are accessible.
252→  // Skip when running as root (uid 0), as the container's node user (uid 1000),
253→  // or when getuid is unavailable (native Windows without WSL).
254→  const hostUid = process.getuid?.();
255→  const hostGid = process.getgid?.();
256→  if (hostUid != null && hostUid !== 0 && hostUid !== 1000) {
257→    args.push('--user', `${hostUid}:${hostGid}`);
258→    args.push('-e', 'HOME=/home/node');
259→  }
260→
261→  for (const mount of mounts) {
262→    if (mount.readonly) {
263→      args.push(...readonlyMountArgs(mount.hostPath, mount.containerPath));
264→    } else {
265→      args.push('-v', `${mount.hostPath}:${mount.containerPath}`);
266→    }
267→  }
268→
269→  args.push(CONTAINER_IMAGE);
270→
271→  return args;
272→}
273→
274→export async function runContainerAgent(
275→  group: RegisteredGroup,
276→  input: ContainerInput,
277→  onProcess: (proc: ChildProcess, containerName: string) => void,
278→  onOutput?: (output: ContainerOutput) => Promise<void>,
279→): Promise<ContainerOutput> {
280→  const startTime = Date.now();
281→
282→  const groupDir = resolveGroupFolderPath(group.folder);
283→  fs.mkdirSync(groupDir, { recursive: true });
284→
285→  const mounts = buildVolumeMounts(group, input.isMain);
286→  const safeName = group.folder.replace(/[^a-zA-Z0-9-]/g, '-');
287→  const containerName = `nanoclaw-${safeName}-${Date.now()}`;
288→  const containerArgs = buildContainerArgs(mounts, containerName);
289→
290→  logger.debug(
291→    {
292→      group: group.name,
293→      containerName,
294→      mounts: mounts.map(
295→        (m) =>
296→          `${m.hostPath} -> ${m.containerPath}${m.readonly ? ' (ro)' : ''}`,
297→      ),
298→      containerArgs: containerArgs.join(' '),
299→    },
300→    'Container mount configuration',
301→  );
302→
303→  logger.info(
304→    {
305→      group: group.name,
306→      containerName,
307→      mountCount: mounts.length,
308→      isMain: input.isMain,
309→    },
310→    'Spawning container agent',
311→  );
312→
313→  const logsDir = path.join(groupDir, 'logs');
314→  fs.mkdirSync(logsDir, { recursive: true });
315→
316→  return new Promise((resolve) => {
317→    const container = spawn(CONTAINER_RUNTIME_BIN, containerArgs, {
318→      stdio: ['pipe', 'pipe', 'pipe'],
319→    });
320→
321→    onProcess(container, containerName);
322→
323→    let stdout = '';
324→    let stderr = '';
325→    let stdoutTruncated = false;
326→    let stderrTruncated = false;
327→
328→    container.stdin.write(JSON.stringify(input));
329→    container.stdin.end();
330→
331→    // Streaming output: parse OUTPUT_START/END marker pairs as they arrive
332→    let parseBuffer = '';
333→    let newSessionId: string | undefined;
334→    let outputChain = Promise.resolve();
335→
336→    container.stdout.on('data', (data) => {
337→      const chunk = data.toString();
338→
339→      // Always accumulate for logging
340→      if (!stdoutTruncated) {
341→        const remaining = CONTAINER_MAX_OUTPUT_SIZE - stdout.length;
342→        if (chunk.length > remaining) {
343→          stdout += chunk.slice(0, remaining);
344→          stdoutTruncated = true;
345→          logger.warn(
346→            { group: group.name, size: stdout.length },
347→            'Container stdout truncated due to size limit',
348→          );
349→        } else {
350→          stdout += chunk;
351→        }
352→      }
353→
354→      // Stream-parse for output markers
355→      if (onOutput) {
356→        parseBuffer += chunk;
357→        let startIdx: number;
358→        while ((startIdx = parseBuffer.indexOf(OUTPUT_START_MARKER)) !== -1) {
359→          const endIdx = parseBuffer.indexOf(OUTPUT_END_MARKER, startIdx);
360→          if (endIdx === -1) break; // Incomplete pair, wait for more data
361→
362→          const jsonStr = parseBuffer
363→            .slice(startIdx + OUTPUT_START_MARKER.length, endIdx)
364→            .trim();
365→          parseBuffer = parseBuffer.slice(endIdx + OUTPUT_END_MARKER.length);
366→
367→          try {
368→            const parsed: ContainerOutput = JSON.parse(jsonStr);
369→            if (parsed.newSessionId) {
370→              newSessionId = parsed.newSessionId;
371→            }
372→            hadStreamingOutput = true;
373→            // Activity detected — reset the hard timeout
374→            resetTimeout();
375→            // Call onOutput for all markers (including null results)
376→            // so idle timers start even for "silent" query completions.
377→            outputChain = outputChain.then(() => onOutput(parsed));
378→          } catch (err) {
379→            logger.warn(
380→              { group: group.name, error: err },
381→              'Failed to parse streamed output chunk',
382→            );
383→          }
384→        }
385→      }
386→    });
387→
388→    container.stderr.on('data', (data) => {
389→      const chunk = data.toString();
390→      const lines = chunk.trim().split('\n');
391→      for (const line of lines) {
392→        if (!line) continue;
393→        if (line.includes('[OLLAMA]')) {
394→          logger.info({ container: group.folder }, line);
395→        } else {
396→          logger.debug({ container: group.folder }, line);
397→        }
398→      }
399→      // Don't reset timeout on stderr — SDK writes debug logs continuously.
400→      // Timeout only resets on actual output (OUTPUT_MARKER in stdout).
401→      if (stderrTruncated) return;
402→      const remaining = CONTAINER_MAX_OUTPUT_SIZE - stderr.length;
403→      if (chunk.length > remaining) {
404→        stderr += chunk.slice(0, remaining);
405→        stderrTruncated = true;
406→        logger.warn(
407→          { group: group.name, size: stderr.length },
408→          'Container stderr truncated due to size limit',
409→        );
410→      } else {
411→        stderr += chunk;
412→      }
413→    });
414→
415→    let timedOut = false;
416→    let hadStreamingOutput = false;
417→    const configTimeout = group.containerConfig?.timeout || CONTAINER_TIMEOUT;
418→    // Grace period: hard timeout must be at least IDLE_TIMEOUT + 30s so the
419→    // graceful _close sentinel has time to trigger before the hard kill fires.
420→    const timeoutMs = Math.max(configTimeout, IDLE_TIMEOUT + 30_000);
421→
422→    const killOnTimeout = () => {
423→      timedOut = true;
424→      logger.error(
425→        { group: group.name, containerName },
426→        'Container timeout, stopping gracefully',
427→      );
428→      exec(stopContainer(containerName), { timeout: 15000 }, (err) => {
429→        if (err) {
430→          logger.warn(
431→            { group: group.name, containerName, err },
432→            'Graceful stop failed, force killing',
433→          );
434→          container.kill('SIGKILL');
435→        }
436→      });
437→    };
438→
439→    let timeout = setTimeout(killOnTimeout, timeoutMs);
440→
441→    // Reset the timeout whenever there's activity (streaming output)
442→    const resetTimeout = () => {
443→      clearTimeout(timeout);
444→      timeout = setTimeout(killOnTimeout, timeoutMs);
445→    };
446→
447→    container.on('close', (code) => {
448→      clearTimeout(timeout);
449→      const duration = Date.now() - startTime;
450→
451→      if (timedOut) {
452→        const ts = new Date().toISOString().replace(/[:.]/g, '-');
453→        const timeoutLog = path.join(logsDir, `container-${ts}.log`);
454→        fs.writeFileSync(
455→          timeoutLog,
456→          [
457→            `=== Container Run Log (TIMEOUT) ===`,
458→            `Timestamp: ${new Date().toISOString()}`,
459→            `Group: ${group.name}`,
460→            `Container: ${containerName}`,
461→            `Duration: ${duration}ms`,
462→            `Exit Code: ${code}`,
463→            `Had Streaming Output: ${hadStreamingOutput}`,
464→          ].join('\n'),
465→        );
466→
467→        // Timeout after output = idle cleanup, not failure.
468→        // The agent already sent its response; this is just the
469→        // container being reaped after the idle period expired.
470→        if (hadStreamingOutput) {
471→          logger.info(
472→            { group: group.name, containerName, duration, code },
473→            'Container timed out after output (idle cleanup)',
474→          );
475→          outputChain.then(() => {
476→            resolve({
477→              status: 'success',
478→              result: null,
479→              newSessionId,
480→            });
481→          });
482→          return;
483→        }
484→
485→        logger.error(
486→          { group: group.name, containerName, duration, code },
487→          'Container timed out with no output',
488→        );
489→
490→        resolve({
491→          status: 'error',
492→          result: null,
493→          error: `Container timed out after ${configTimeout}ms`,
494→        });
495→        return;
496→      }
497→
498→      const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
499→      const logFile = path.join(logsDir, `container-${timestamp}.log`);
500→      const isVerbose =
501→        process.env.LOG_LEVEL === 'debug' || process.env.LOG_LEVEL === 'trace';
502→
503→      const logLines = [
504→        `=== Container Run Log ===`,
505→        `Timestamp: ${new Date().toISOString()}`,
506→        `Group: ${group.name}`,
507→        `IsMain: ${input.isMain}`,
508→        `Duration: ${duration}ms`,
509→        `Exit Code: ${code}`,
510→        `Stdout Truncated: ${stdoutTruncated}`,
511→        `Stderr Truncated: ${stderrTruncated}`,
512→        ``,
513→      ];
514→
515→      const isError = code !== 0;
516→
517→      if (isVerbose || isError) {
518→        // On error, log input metadata only — not the full prompt.
519→        // Full input is only included at verbose level to avoid
520→        // persisting user conversation content on every non-zero exit.
521→        if (isVerbose) {
522→          logLines.push(`=== Input ===`, JSON.stringify(input, null, 2), ``);
523→        } else {
524→          logLines.push(
525→            `=== Input Summary ===`,
526→            `Prompt length: ${input.prompt.length} chars`,
527→            `Session ID: ${input.sessionId || 'new'}`,
528→            ``,
529→          );
530→        }
531→        logLines.push(
532→          `=== Container Args ===`,
533→          containerArgs.join(' '),
534→          ``,
535→          `=== Mounts ===`,
536→          mounts
537→            .map(
538→              (m) =>
539→                `${m.hostPath} -> ${m.containerPath}${m.readonly ? ' (ro)' : ''}`,
540→            )
541→            .join('\n'),
542→          ``,
543→          `=== Stderr${stderrTruncated ? ' (TRUNCATED)' : ''} ===`,
544→          stderr,
545→          ``,
546→          `=== Stdout${stdoutTruncated ? ' (TRUNCATED)' : ''} ===`,
547→          stdout,
548→        );
549→      } else {
550→        logLines.push(
551→          `=== Input Summary ===`,
552→          `Prompt length: ${input.prompt.length} chars`,
553→          `Session ID: ${input.sessionId || 'new'}`,
554→          ``,
555→          `=== Mounts ===`,
556→          mounts
557→            .map((m) => `${m.containerPath}${m.readonly ? ' (ro)' : ''}`)
558→            .join('\n'),
559→          ``,
560→        );
561→      }
562→
563→      fs.writeFileSync(logFile, logLines.join('\n'));
564→      logger.debug({ logFile, verbose: isVerbose }, 'Container log written');
565→
566→      if (code !== 0) {
567→        logger.error(
568→          {
569→            group: group.name,
570→            code,
571→            duration,
572→            stderr,
573→            stdout,
574→            logFile,
575→          },
576→          'Container exited with error',
577→        );
578→
579→        resolve({
580→          status: 'error',
581→          result: null,
582→          error: `Container exited with code ${code}: ${stderr.slice(-200)}`,
583→        });
584→        return;
585→      }
586→
587→      // Streaming mode: wait for output chain to settle, return completion marker
588→      if (onOutput) {
589→        outputChain.then(() => {
590→          logger.info(
591→            { group: group.name, duration, newSessionId },
592→            'Container completed (streaming mode)',
593→          );
594→          resolve({
595→            status: 'success',
596→            result: null,
597→            newSessionId,
598→          });
599→        });
600→        return;
601→      }
602→
603→      // Legacy mode: parse the last output marker pair from accumulated stdout
604→      try {
605→        // Extract JSON between sentinel markers for robust parsing
606→        const startIdx = stdout.indexOf(OUTPUT_START_MARKER);
607→        const endIdx = stdout.indexOf(OUTPUT_END_MARKER);
608→
609→        let jsonLine: string;
610→        if (startIdx !== -1 && endIdx !== -1 && endIdx > startIdx) {
611→          jsonLine = stdout
612→            .slice(startIdx + OUTPUT_START_MARKER.length, endIdx)
613→            .trim();
614→        } else {
615→          // Fallback: last non-empty line (backwards compatibility)
616→          const lines = stdout.trim().split('\n');
617→          jsonLine = lines[lines.length - 1];
618→        }
619→
620→        const output: ContainerOutput = JSON.parse(jsonLine);
621→
622→        logger.info(
623→          {
624→            group: group.name,
625→            duration,
626→            status: output.status,
627→            hasResult: !!output.result,
628→          },
629→          'Container completed',
630→        );
631→
632→        resolve(output);
633→      } catch (err) {
634→        logger.error(
635→          {
636→            group: group.name,
637→            stdout,
638→            stderr,
639→            error: err,
640→          },
641→          'Failed to parse container output',
642→        );
643→
644→        resolve({
645→          status: 'error',
646→          result: null,
647→          error: `Failed to parse container output: ${err instanceof Error ? err.message : String(err)}`,
648→        });
649→      }
650→    });
651→
652→    container.on('error', (err) => {
653→      clearTimeout(timeout);
654→      logger.error(
655→        { group: group.name, containerName, error: err },
656→        'Container spawn error',
657→      );
658→      resolve({
659→        status: 'error',
660→        result: null,
661→        error: `Container spawn error: ${err.message}`,
662→      });
663→    });
664→  });
665→}
