667→export function writeTasksSnapshot(
668→  groupFolder: string,
669→  isMain: boolean,
670→  tasks: Array<{
671→    id: string;
672→    groupFolder: string;
673→    prompt: string;
674→    schedule_type: string;
675→    schedule_value: string;
676→    status: string;
677→    next_run: string | null;
678→  }>,
679→): void {
680→  // Write filtered tasks to the group's IPC directory
681→  const groupIpcDir = resolveGroupIpcPath(groupFolder);
682→  fs.mkdirSync(groupIpcDir, { recursive: true });
683→
684→  // Main sees all tasks, others only see their own
685→  const filteredTasks = isMain
686→    ? tasks
687→    : tasks.filter((t) => t.groupFolder === groupFolder);
688→
689→  const tasksFile = path.join(groupIpcDir, 'current_tasks.json');
690→  fs.writeFileSync(tasksFile, JSON.stringify(filteredTasks, null, 2));
691→}
