700→/**
701→ * Write available groups snapshot for the container to read.
702→ * Only main group can see all available groups (for activation).
703→ * Non-main groups only see their own registration status.
704→ */
705→export function writeGroupsSnapshot(
706→  groupFolder: string,
707→  isMain: boolean,
708→  groups: AvailableGroup[],
709→  _registeredJids: Set<string>,
710→): void {
711→  const groupIpcDir = resolveGroupIpcPath(groupFolder);
712→  fs.mkdirSync(groupIpcDir, { recursive: true });
713→
714→  // Main sees all groups; others see nothing (they can't activate groups)
715→  const visibleGroups = isMain ? groups : [];
716→
717→  const groupsFile = path.join(groupIpcDir, 'available_groups.json');
718→  fs.writeFileSync(
719→    groupsFile,
720→    JSON.stringify(
721→      {
722→        groups: visibleGroups,
723→        lastSync: new Date().toISOString(),
724→      },
725→      null,
726→      2,
727→    ),
728→  );
729→}
